import java.nio.charset.StandardCharsets;

interface Shape { double area(); }
class Circle implements Shape {
    double r;
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
}
class Square implements Shape {
    double s;
    Square(double s) { this.s = s; }
    public double area() { return s * s; }
}
public class Main {
    public static void main(String[] args) throws Exception {
        String input = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).trim();
        if (input.equals("__invalid__")) System.exit(1);
        String[] parts = input.split("\\s+");
        Shape sh;
        if (parts[0].equals("circle")) sh = new Circle(Double.parseDouble(parts[1]));
        else sh = new Square(Double.parseDouble(parts[1]));
        System.out.println(Math.round(sh.area()));
    }
}
